(function(){
  'use strict';
  const content=document.getElementById('content'),input=document.getElementById('search'),clear=document.getElementById('clear-search');
  const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg>';
  const backIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6M8 12h12"/></svg>';
  const copyIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="8" width="11" height="12" rx="2"/><path d="M15 8V4H4v12h4"/></svg>';
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let model,limit=40,debounce,toastTimer,lastFocus=null,copyIds=[];
  try{if(!Array.isArray(window.UNGM_DATA))throw new Error('Missing directory');model=window.UNGM_MODEL.createModel(window.UNGM_DATA);}catch(e){content.innerHTML='<div class="empty-state"><h2>The directory could not load</h2><p>Refresh the page to try again.</p><button class="primary" id="retry">Try again</button></div>';document.getElementById('retry').onclick=()=>location.reload();document.getElementById('data-label').textContent='Directory unavailable';return;}
  document.getElementById('data-label').textContent='10 categories · '+model.sourceCount.toLocaleString()+' entries';
  function state(){const p=new URLSearchParams(location.hash.slice(1));return{node:p.get('browse')||'',query:p.get('q')||'',scope:p.get('scope')||'',finalOnly:p.get('groups')!=='1',from:p.get('from')||''};}
  function go(next,{replace=false,focus=true}={}){const p=new URLSearchParams();if(next.node)p.set('browse',next.node);if(next.query)p.set('q',next.query);if(next.scope)p.set('scope',next.scope);if(next.finalOnly===false)p.set('groups','1');if(next.from)p.set('from',next.from);const hash=p.toString()?'#'+p.toString():location.pathname;history[replace?'replaceState':'pushState'](null,'',hash);limit=40;render(focus);}
  function breadcrumb(nodes,current=''){return '<aside class="journey" aria-label="Your choices"><h2>Your choices</h2><ol><li'+(!nodes.length?' aria-current="step"':'')+'><button data-home>All categories</button></li>'+nodes.map((n,i)=>'<li'+(n.id===current?' aria-current="step"':'')+'><button data-open="'+esc(n.id)+'"><span class="journey-small">'+(i===0?'Category '+n.code:n.code||'Source note')+'</span>'+esc(i===0?model.shortNames[n.code]:n.name)+'</button></li>').join('')+'</ol>'+(nodes.length?'<button class="text-button start-over" data-home>'+backIcon+'Start over</button>':'')+'<p class="reading-note">Choose what best describes your item. Copy the current list to Excel using the button at the bottom.</p></aside>';}
  function stepLabel(depth,isFinal){return '<div class="step-label"><span class="step-dots" aria-hidden="true">'+Array.from({length:Math.max(4,depth+1)},(_,i)=>'<i class="'+(i<=depth?'done':'')+'"></i>').join('')+'</span>'+(isFinal?'Ready to copy':'Step '+(depth+1)+' · '+(depth===0?'Choose a category':'Narrow your choice'))+'</div>';}
  function header(title,sub,{back='',depth=0,final=false}={}){return stepLabel(depth,final)+'<div class="section-heading"><div><h2 id="view-title" tabindex="-1">'+esc(title)+'</h2>'+(sub?'<p>'+esc(sub)+'</p>':'')+'</div>'+(back!==''?'<button class="back-button" '+(back==='home'?'data-home':'data-open="'+esc(back)+'"')+'>'+backIcon+'Back</button>':'')+'</div>';}
  function copyFooter(items,{search=false}={}){copyIds=items.filter(n=>!n.synthetic&&n.code).map(n=>n.id);if(!copyIds.length)return '';const count=copyIds.length;return '<div class="copy-list-footer"><p><strong>'+count.toLocaleString()+' '+(count===1?'entry':'entries')+'</strong><span>'+(search?'Copies all matching results, including those not yet shown.':'Copies the entries with codes listed above.')+' Two columns: Code and Name.</span></p><button class="primary" data-copy-list aria-label="Copy '+count+' '+(count===1?'entry':'entries')+' for Excel">'+copyIcon+'Copy list for Excel</button></div>';}
  const warning='<p class="warning">These 18 entries have missing parent links in the UNGM export. They are kept under category H because their segment is humanitarian relief. Their exact position in the original hierarchy is unverified.</p>';
  function pathText(n){return model.path(n.id).slice(0,-1).map((v,i)=>i===0?model.shortNames[v.code]:v.name).join(' › ');}
  function highlight(text,query){const tokens=query.trim().split(/\s+/).filter(Boolean).sort((a,b)=>b.length-a.length);if(!tokens.length)return esc(text);const pattern=tokens.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|');return String(text).split(new RegExp('('+pattern+')','ig')).map((s,i)=>i%2?'<mark>'+esc(s)+'</mark>':esc(s)).join('');}
  function finalRow(n,{query='',showPath=false}={}){return '<article class="choice-row">'+(showPath?'<p class="path-line">'+esc(pathText(n))+'</p>':'')+'<span class="final-code">'+highlight(n.code,query)+'</span><button class="result-title" data-open="'+esc(n.id)+'">'+highlight(n.name,query)+'</button>'+(n.warning?'<p class="warning small">Exact parent information is missing from the source export.</p>':'')+'</article>';}
  function groupRow(n,{query='',showPath=false}={}){return '<div class="choice-row">'+(showPath?'<p class="path-line">'+esc(pathText(n))+'</p>':'')+'<button class="choice-button" data-open="'+esc(n.id)+'"><span class="choice-main"><span class="choice-name">'+highlight(n.name,query)+'</span><span class="choice-code">'+(n.code?esc(n.code)+' · ':'')+n.children.length+' '+(n.children.length===1?'choice':'choices')+'</span></span><span class="choice-meta">Open group</span>'+arrow+'</button></div>';}
  function home(){return breadcrumb([])+'<div class="browse-main step-enter">'+header('Choose a category','Start with the area that best describes your goods or services.')+'<div class="category-grid">'+model.roots.map(n=>'<button class="category-choice" data-open="'+n.id+'" title="'+esc(n.name)+'"><span class="category-letter">'+n.code+'</span><span class="category-text"><strong>'+esc(model.shortNames[n.code])+'</strong><small>'+n.children.length+' groups · '+model.finalCount(n.id).toLocaleString()+' final codes</small></span>'+arrow+'</button>').join('')+'</div>'+copyFooter(model.roots)+'</div>';}
  function browse(n,s){const trail=model.path(n.id),isFinal=model.isFinal(n),parent=model.nodes.has(n.parent)?n.parent:'home';
    if(isFinal)return breadcrumb(trail,n.id)+'<div class="browse-main step-enter">'+header('Your code is ready','Copy this result as two columns using the button below.',{back:parent,depth:trail.length-1,final:true})+'<div class="result-detail"><span class="final-code">'+esc(n.code)+'</span><h2>'+esc(n.name)+'</h2><p class="detail-note">This is the most specific entry available in this directory for this branch.</p>'+(n.warning?warning:'')+'</div>'+copyFooter([n])+'</div>';
    const items=n.children.map(id=>model.nodes.get(id)),allFinal=items.length&&items.every(model.isFinal);
    return breadcrumb(trail,n.id)+'<div class="browse-main step-enter">'+header(n.name,allFinal?'Review the items below. Use the button at the bottom to copy this list to Excel.':'Choose the option that best matches what you need.',{back:parent,depth:trail.length})+(n.synthetic?warning:'')+'<div class="choice-list">'+items.map(x=>model.isFinal(x)?finalRow(x):groupRow(x)).join('')+'</div>'+copyFooter(items)+'</div>';
  }
  function searchView(s){const results=model.search(s.query,{finalOnly:s.finalOnly,scope:s.scope});const shown=results.slice(0,limit);return breadcrumb([])+'<div class="browse-main step-enter"><div class="section-heading"><div><h2 id="view-title" tabindex="-1">Search results</h2><p>'+results.length.toLocaleString()+' '+(results.length===1?'match':'matches')+' for “'+esc(s.query)+'”</p></div><button class="back-button" data-home>'+backIcon+'Browse categories</button></div><div class="filters"><label for="scope">Search in <select id="scope"><option value="">All categories</option>'+model.roots.map(n=>'<option value="'+n.id+'"'+(n.id===s.scope?' selected':'')+'>'+n.code+' · '+esc(model.shortNames[n.code])+'</option>').join('')+'</select></label><label><input id="final-only" type="checkbox"'+(s.finalOnly?' checked':'')+'>Final codes only</label></div>'+(results.length?'<p class="search-notice">'+(s.finalOnly?'Copy these results to Excel using the button at the bottom.':'Groups open the next set of choices. The button at the bottom copies the matching results.')+'</p><div class="choice-list">'+shown.map(n=>model.isFinal(n)?finalRow(n,{query:s.query,showPath:true}):groupRow(n,{query:s.query,showPath:true})).join('')+'</div>'+(results.length>limit?'<button class="copy-button show-more" data-more>Show '+Math.min(40,results.length-limit)+' more results</button>':'')+copyFooter(results,{search:true}):'<div class="empty-state"><h3>No matching '+(s.finalOnly?'final codes':'entries')+'</h3><p>Try a shorter phrase, a different word, or part of a code. '+(s.finalOnly?'You can also untick “Final codes only” to search broader groups.':'You can browse the categories to find the closest match.')+'</p><button class="copy-button" data-home>Browse all categories</button></div>')+'</div>';}
  function render(focus=false){copyIds=[];const s=state(),node=model.nodes.get(s.node);input.value=s.query;clear.hidden=!s.query;document.body.classList.toggle('is-browsing',!!node||!!s.query);content.className='workspace workspace-layout';content.innerHTML=s.query?searchView(s):node?browse(node,s):home();document.title=(s.query?'Search: '+s.query:node?node.name:'Find a code')+' · UNGM Code Finder';if(focus){const title=document.getElementById('view-title');if(title){title.focus({preventScroll:true});content.scrollIntoView({block:'start',behavior:'auto'});}}}
  function runSearch(replace=false){const q=input.value.trim();const s=state();go({query:q,scope:s.scope,finalOnly:s.finalOnly},{replace,focus:false});}
  document.getElementById('search-form').addEventListener('submit',e=>{e.preventDefault();clearTimeout(debounce);runSearch(false);});
  input.addEventListener('input',()=>{clear.hidden=!input.value;clearTimeout(debounce);debounce=setTimeout(()=>runSearch(true),180);});
  clear.addEventListener('click',()=>{clearTimeout(debounce);input.value='';go({},{focus:false});input.focus();});
  document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.example;runSearch();}));
  document.getElementById('help-toggle').addEventListener('click',e=>{const help=document.getElementById('help');help.hidden=!help.hidden;e.currentTarget.setAttribute('aria-expanded',String(!help.hidden));});
  content.addEventListener('change',e=>{const s=state(),id=e.target.id;if(id==='scope')go({...s,scope:e.target.value},{replace:true,focus:false});if(id==='final-only')go({...s,finalOnly:e.target.checked},{replace:true,focus:false});if(id==='scope'||id==='final-only')document.getElementById(id)?.focus({preventScroll:true});});
  content.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-home')){clearTimeout(debounce);go({});return;}if(b.dataset.open){clearTimeout(debounce);go({node:b.dataset.open});return;}if(b.hasAttribute('data-more')){const firstNew=limit;limit+=40;render(false);const target=content.querySelectorAll('.choice-row')[firstNew]?.querySelector('button')||document.querySelector('[data-more]')||document.getElementById('view-title');target?.focus({preventScroll:true});return;}if(b.hasAttribute('data-copy-list')){await copy(model.excelText(copyIds),b);}});
  function announce(message){const t=document.getElementById('toast');clearTimeout(toastTimer);t.textContent=message;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),2600);}
  async function copy(text,button){try{if(!navigator.clipboard?.writeText)throw new Error('No clipboard API');await navigator.clipboard.writeText(text);announce('Copied to clipboard');}catch(e){const temp=document.createElement('textarea');temp.value=text;temp.style.position='fixed';temp.style.left='-9999px';document.body.appendChild(temp);temp.select();let success=false;try{success=document.execCommand('copy');}catch{}temp.remove();button.focus({preventScroll:true});if(success)announce('Copied to clipboard');else{lastFocus=button;const panel=document.getElementById('manual-copy'),field=document.getElementById('manual-text');panel.hidden=false;field.value=text;panel.scrollIntoView({block:'center'});field.focus();field.select();announce('Select the text below to copy it');}}}
  document.getElementById('close-manual').onclick=()=>{document.getElementById('manual-copy').hidden=true;if(lastFocus?.isConnected)lastFocus.focus();};
  window.addEventListener('hashchange',()=>{limit=40;render(true);});window.addEventListener('popstate',()=>{limit=40;render(true);});
  render();
})();
